121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
128	
129	    compiled.push(spec);
