import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from './src/engine.js';
import assert from 'node:assert/strict';

const linear = message => ({
  id: 'w', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'note' },
    { id: 'note', type: 'action', message, next: 'done' },
    { id: 'done', type: 'end', result: 'ok' },
  ],
});

// 1. getter: ordinary at validation, shared at execution (sync + async)
{
  let reads = 0;
  const msg = { get flip() { reads += 1; return reads === 1 ? 'ordinary' : new SharedArrayBuffer(4); } };
  const wf = linear(msg);
  assert.doesNotThrow(() => validateWorkflow(wf));
  assert.throws(() => executeWorkflow(wf, {}), /action node note: message contains shared memory.*independent copies cannot be guaranteed/s);
  assert.equal(reads, 2, 'one validation read + one execution read');
}
{
  let reads = 0;
  const msg = { get flip() { reads += 1; return reads === 1 ? 'ordinary' : new Uint8Array(new SharedArrayBuffer(4)); } };
  const wf = linear(msg);
  await assert.rejects(() => executeWorkflowAsync(wf, {}), /action node note: message contains shared memory/);
  assert.equal(reads, 2);
}

// 2. preceding business op swaps plain buffer for shared; no compensation, no retries
{
  const wf = {
    id: 'w2', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'a' },
      { id: 'a', type: 'action', operation: 'opA', compensation: { operation: 'undoA' }, next: 'note' },
      { id: 'note', type: 'action', message: { bytes: new Uint8Array([1,2]) }, next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  let comp = 0;
  await assert.rejects(() => executeWorkflowAsync(wf, {}, {
    opA: () => { wf.nodes[2].message.bytes = new Uint8Array(new SharedArrayBuffer(2)); return 'A'; },
    undoA: () => { comp += 1; return 'u'; },
  }), /action node note: message contains shared memory/);
  assert.equal(comp, 0, 'no compensation');
}

// 3. uncloneable at execution (function appears) -> cloneability error
{
  let reads = 0;
  const msg = { get flip() { reads += 1; return reads === 1 ? 'ok' : () => 'nope'; } };
  assert.throws(() => executeWorkflow(linear(msg), {}), /action node note: message must be a structured-cloneable value/);
}

// 4. getter throws at execution -> cloneability error
{
  let reads = 0;
  const msg = { get boom() { reads += 1; if (reads === 1) return 'calm'; throw new Error('x'); } };
  assert.throws(() => executeWorkflow(linear(msg), {}), /action node note: message must be a structured-cloneable value/);
}

// 5. root message read exactly once at execution
{
  let rootReads = 0;
  const wf = {
    id: 'w5', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'note' },
      { id: 'note', type: 'action', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  Object.defineProperty(wf.nodes[1], 'message', { enumerable: true, get() { rootReads += 1; return { v: 1 }; } });
  const run = executeWorkflow(wf, {});
  assert.equal(run.status, 'completed');
  assert.deepEqual(run.context.output.note, { v: 1 });
  assert.equal(rootReads, 1, 'root read once');
}

// 6. plain ArrayBuffer still fine, independent
{
  const wf = linear(Uint8Array.from([1,2,3]).buffer);
  const run = executeWorkflow(wf, {});
  assert.ok(run.context.output.note instanceof ArrayBuffer);
  assert.deepEqual([...new Uint8Array(run.context.output.note)], [1,2,3]);
}

// 7. shared memory only in clone-dropped property -> accepted
{
  const msg = { when: new Date(0) };
  msg.when.aux = new SharedArrayBuffer(4);
  const run = executeWorkflow(linear(msg), {});
  assert.equal(run.status, 'completed');
  assert.equal(run.context.output.note.when.aux, undefined);
}

// 8. defaults unchanged
{
  assert.equal(executeWorkflow(linear(undefined), {}).context.output.note, 'action:note');
  assert.equal(executeWorkflow(linear(null), {}).context.output.note, 'action:note');
  assert.equal(executeWorkflow(linear(''), {}).context.output.note, '');
  assert.equal(executeWorkflow(linear(0), {}).context.output.note, 0);
  assert.equal(executeWorkflow(linear(false), {}).context.output.note, false);
}

// 9. no output left, successors never run on failure
{
  const msg = { get flip() { let n = 0; return ++n === 1 ? 'ok' : new SharedArrayBuffer(2); } };
  // rebuild getter properly: needs closure per-read
  let r = 0;
  const msg2 = { get flip() { r += 1; return r === 1 ? 'ok' : new SharedArrayBuffer(2); } };
  const wf = {
    id: 'w9', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'note' },
      { id: 'note', type: 'action', message: msg2, next: 'after' },
      { id: 'after', type: 'action', message: 'should-not-run', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  try { executeWorkflow(wf, {}); assert.fail('should throw'); }
  catch (e) { assert.match(e.message, /action node note: message contains shared memory/); }
}
console.log('all sanity checks passed');
"

