    work: () => {
      const next = new Uint8Array([9, 8, 7, 6]);
      workflow.nodes[2].message.bytes = next;
      workflow.nodes[2].message.nested.label = 'after';
      workflow.nodes[2].message.nested.list.push(3);
      return 'done';
